import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';

const STATUS_CFG = {
  draft:            { label: 'Draft',            cls: 'badge-gray'  },
  pending_manager:  { label: 'Pending Manager',  cls: 'badge-amber' },
  pending_hr_head:  { label: 'Pending HR Head',  cls: 'badge-amber' },
  approved:         { label: 'Approved',         cls: 'badge-green' },
  rejected:         { label: 'Rejected',         cls: 'badge-red'   },
  issued:           { label: 'Issued',           cls: 'badge-green' },
  withdrawn:        { label: 'Withdrawn',        cls: 'badge-red'   },
};

// Per workflow document: only draft + rejected are deletable; approved/issued/withdrawn
// are permanent audit records that must never be destroyed.
const DELETABLE_STATUSES = new Set(['draft', 'rejected']);
const DELETE_ROLES       = new Set(['admin', 'hr_head']);

// ── Generate Modal ──────────────────────────────────────────────────────────

function GenerateModal({ employees, templates, onClose, onDone }) {
  const [step, setStep] = useState(1);
  const [form, setForm] = useState({
    employee_id: '', template_id: '',
    company_name: 'Acme Corp',
    hr_signatory_name: '', hr_signatory_designation: 'HR Manager',
    extra_fields: {},
  });
  const [error,   setError]   = useState('');
  const [loading, setLoading] = useState(false);

  const selectedTemplate = templates.find(t => t._id === form.template_id);
  const selectedEmployee = employees.find(e => e._id === form.employee_id);

  const generate = async () => {
    setError(''); setLoading(true);
    try {
      await axios.post('/api/letters/generate', form);
      onDone();
    } catch (e) {
      setError(e.response?.data?.error || 'Generation failed');
    } finally { setLoading(false); }
  };

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal" style={{ maxWidth: 560 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <h2 className="modal-title" style={{ margin: 0 }}>Generate Offer Letter</h2>
          <div style={{ display: 'flex', gap: 6 }}>
            {[1, 2].map(s => (
              <div key={s} style={{
                width: 28, height: 28, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontSize: 12, fontWeight: 600, fontFamily: 'var(--mono)',
                background: step === s ? 'var(--accent)' : step > s ? 'var(--green-dim)' : 'var(--surface-2)',
                color: step === s ? 'white' : step > s ? 'var(--green)' : 'var(--text-dim)',
                border: `1px solid ${step === s ? 'var(--accent)' : step > s ? 'var(--green)' : 'var(--border)'}`,
              }}>{s}</div>
            ))}
          </div>
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        {step === 1 && (
          <>
            <div className="form-group">
              <label className="form-label">Employee *</label>
              <select value={form.employee_id} onChange={e => setForm({ ...form, employee_id: e.target.value })}>
                <option value="">Select employee...</option>
                {employees.map(emp => (
                  <option key={emp._id} value={emp._id}>{emp.name} — {emp.employee_id} — {emp.designation}</option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label className="form-label">Template *</label>
              <select value={form.template_id} onChange={e => setForm({ ...form, template_id: e.target.value })}>
                <option value="">Select template...</option>
                {templates.map(t => <option key={t._id} value={t._id}>{t.name} (v{t.version})</option>)}
              </select>
            </div>
            {selectedEmployee && (
              <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 12, marginBottom: 16, fontSize: 12 }}>
                <div style={{ fontSize: 10, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', marginBottom: 8 }}>Employee Preview</div>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 }}>
                  {[['Name', selectedEmployee.name], ['ID', selectedEmployee.employee_id], ['Role', selectedEmployee.designation], ['Dept', selectedEmployee.department], ['CTC', '₹' + selectedEmployee.ctc], ['Joining', selectedEmployee.joining_date]].map(([k, v]) => v ? (
                    <div key={k}><span style={{ color: 'var(--text-dim)' }}>{k}: </span><span style={{ fontWeight: 500 }}>{v}</span></div>
                  ) : null)}
                </div>
              </div>
            )}
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={onClose}>Cancel</button>
              <button className="btn btn-primary" onClick={() => setStep(2)} disabled={!form.employee_id || !form.template_id}>Next →</button>
            </div>
          </>
        )}

        {step === 2 && (
          <>
            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Company Name</label>
                <input value={form.company_name} onChange={e => setForm({ ...form, company_name: e.target.value })} />
              </div>
              <div className="form-group">
                <label className="form-label">Signatory Name</label>
                <input value={form.hr_signatory_name} onChange={e => setForm({ ...form, hr_signatory_name: e.target.value })} placeholder="e.g. Priya Sharma" />
              </div>
            </div>
            <div className="form-group">
              <label className="form-label">Signatory Designation</label>
              <input value={form.hr_signatory_designation} onChange={e => setForm({ ...form, hr_signatory_designation: e.target.value })} />
            </div>
            {selectedTemplate?.placeholders?.filter(p => !['employee_name','employee_id','designation','department','ctc','basic','hra','allowances','joining_date','address','probation_period','notice_period','company_name','hr_signatory_name','hr_signatory_designation','date'].includes(p)).map(p => (
              <div className="form-group" key={p}>
                <label className="form-label">{p.replace(/_/g, ' ')}</label>
                <input value={form.extra_fields[p] || ''} onChange={e => setForm({ ...form, extra_fields: { ...form.extra_fields, [p]: e.target.value } })} placeholder={`{{${p}}}`} />
              </div>
            ))}
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setStep(1)}>← Back</button>
              <button className="btn btn-primary" onClick={generate} disabled={loading}>
                {loading ? 'Generating...' : '◈ Generate Letter'}
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// ── Delete Confirm Modal ─────────────────────────────────────────────────────

function DeleteLetterModal({ letter, onClose, onDone }) {
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');

  const confirm = async () => {
    setLoading(true); setError('');
    try {
      await axios.delete(`/api/letters/${letter._id}`);
      onDone(`Letter for ${letter.employee_name} (${letter.status}) deleted.`);
    } catch (e) {
      setError(e.response?.data?.error || 'Delete failed');
      setLoading(false);
    }
  };

  const cfg = STATUS_CFG[letter.status] || {};

  return (
    <div className="modal-overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal" style={{ maxWidth: 440 }}>
        <h2 className="modal-title" style={{ color: 'var(--red)' }}>⚠ Delete Offer Letter</h2>

        <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 14, marginBottom: 16 }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10, fontSize: 13 }}>
            {[['Employee', letter.employee_name], ['Code', letter.employee_code], ['Status', letter.status], ['Version', `v${letter.version}`]].map(([k, v]) => (
              <div key={k}>
                <div style={{ fontSize: 10, fontFamily: 'var(--mono)', color: 'var(--text-dim)', textTransform: 'uppercase', marginBottom: 2 }}>{k}</div>
                <div style={{ fontWeight: 500 }}>
                  {k === 'Status' ? <span className={`badge ${cfg.cls}`}>{cfg.label}</span> : v}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div style={{ background: 'var(--red-dim)', border: '1px solid rgba(240,82,82,0.25)', borderRadius: 'var(--radius)', padding: '10px 14px', marginBottom: 16, fontSize: 12, color: 'var(--red)', lineHeight: 1.6 }}>
          <strong>This action is permanent.</strong> The letter record and all associated files
          will be removed from the system. This action is logged against your account.
          <br /><br />
          <strong>Note:</strong> Approved, Issued and Withdrawn letters cannot be deleted — they
          are permanent audit records as per the Offer Letter Lifecycle policy.
        </div>

        {error && <div className="alert alert-error">{error}</div>}

        <div className="modal-footer">
          <button className="btn btn-secondary" onClick={onClose} disabled={loading}>Cancel</button>
          <button className="btn btn-danger" onClick={confirm} disabled={loading}
            style={{ background: 'var(--red)', borderColor: 'var(--red)', color: 'white' }}>
            {loading ? 'Deleting...' : '✕ Delete Permanently'}
          </button>
        </div>
      </div>
    </div>
  );
}

// ── Main LettersPage ─────────────────────────────────────────────────────────

export default function LettersPage() {
  const { user }                    = useAuth();
  const [letters,      setLetters]  = useState([]);
  const [employees,    setEmployees]= useState([]);
  const [templates,    setTemplates]= useState([]);
  const [loading,      setLoading]  = useState(true);
  const [showGen,      setShowGen]  = useState(false);
  const [submitTarget, setSubmit]   = useState(null);
  const [deleteTarget, setDelete]   = useState(null);
  const [success,      setSuccess]  = useState('');
  const [error,        setError]    = useState('');

  // ── Tab: "Active" (draft/pending/rejected) vs "Completed" (approved/issued/withdrawn)
  const [tab,          setTab]      = useState('active');
  // ── Status sub-filter within the active tab
  const [filterStatus, setFilter]   = useState('');

  const canDelete = DELETE_ROLES.has(user?.role);

  const load = useCallback(() => {
    setLoading(true);
    // Build query: tab determines the base set; filterStatus narrows further
    let qs = filterStatus ? `?status=${filterStatus}` : `?tab=${tab}`;
    axios.get(`/api/letters/${qs}`)
      .then(r => setLetters(r.data))
      .finally(() => setLoading(false));
  }, [tab, filterStatus]);

  useEffect(() => { load(); }, [load]);

  // Reset sub-filter when switching tabs
  const switchTab = (t) => { setTab(t); setFilter(''); };

  useEffect(() => {
    axios.get('/api/employees/?status=active').then(r => setEmployees(r.data));
    axios.get('/api/templates/?type=offer').then(r => setTemplates(r.data.filter(t => t.is_active)));
  }, []);

  const notify = (msg) => { setSuccess(msg); setTimeout(() => setSuccess(''), 5000); };

  const handleDone = () => { setShowGen(false); load(); notify('Letter generated! Review and submit for approval.'); };

  const submitLetter = async () => {
    try {
      await axios.post(`/api/letters/${submitTarget._id}/submit`, {});
      setSubmit(null); load(); notify('Submitted for manager approval.');
    } catch (e) {
      setError(e.response?.data?.error || 'Submit failed');
    }
  };

  const download = (id, fmt) =>
    axios.get(`/api/letters/${id}/download?format=${fmt}`, { responseType: 'blob' })
      .then(r => {
        const url = URL.createObjectURL(r.data);
        const a = document.createElement('a'); a.href = url; a.download = `offer_letter.${fmt}`; a.click();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
      })
      .catch(e => setError(e.response?.data?.error || 'File not available'));

  const onDeleteDone = (msg) => { setDelete(null); load(); notify(msg); };

  // Status filter buttons for the ACTIVE tab
  const ACTIVE_FILTERS  = ['draft', 'pending_manager', 'pending_hr_head', 'rejected'];
  const COMP_FILTERS    = ['approved', 'issued', 'withdrawn'];
  const currentFilters  = tab === 'active' ? ACTIVE_FILTERS : COMP_FILTERS;

  return (
    <div>
      <div className="page-header">
        <div>
          <h1 className="page-title">Offer Letters</h1>
          <p className="page-subtitle">{letters.length} letter{letters.length !== 1 ? 's' : ''} shown</p>
        </div>
        <button className="btn btn-primary" onClick={() => setShowGen(true)}>◈ Generate Letter</button>
      </div>

      {success && <div className="alert alert-success">{success}</div>}
      {error   && <div className="alert alert-error" onClick={() => setError('')} style={{ cursor: 'pointer' }}>{error} ✕</div>}

      {/* ── Permission notice for delete-capable roles ── */}
      {canDelete && (
        <div style={{ background: 'var(--amber-dim)', border: '1px solid rgba(245,166,35,0.25)', borderRadius: 'var(--radius)', padding: '8px 14px', marginBottom: 16, fontSize: 12, color: 'var(--amber)', display: 'flex', alignItems: 'center', gap: 8 }}>
          <span>⚠</span>
          <span>You have <strong>{user.role === 'admin' ? 'Admin' : 'HR Head'}</strong> privileges. Draft and Rejected letters can be permanently deleted. Approved / Issued / Withdrawn letters are protected audit records.</span>
        </div>
      )}

      {/* ── Active / Completed tab switcher (mirrors Approvals Pending/History) ── */}
      <div style={{ display: 'flex', gap: 4, marginBottom: 16, background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 'var(--radius)', padding: 4, width: 'fit-content' }}>
        {[['active', 'Active Letters'], ['completed', 'Completed Letters']].map(([key, label]) => (
          <button key={key}
            className={`btn btn-sm ${tab === key ? 'btn-primary' : 'btn-ghost'}`}
            onClick={() => switchTab(key)}
            style={{ fontSize: 12 }}>
            {label}
          </button>
        ))}
      </div>

      {/* ── Status sub-filter within current tab ── */}
      <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap', alignItems: 'center' }}>
        <span style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'var(--mono)' }}>Filter:</span>
        <button
          className={`btn btn-sm ${filterStatus === '' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setFilter('')} style={{ fontSize: 11 }}>All</button>
        {currentFilters.map(s => (
          <button key={s}
            className={`btn btn-sm ${filterStatus === s ? 'btn-primary' : 'btn-secondary'}`}
            onClick={() => setFilter(s)} style={{ fontSize: 11 }}>
            {STATUS_CFG[s]?.label}
          </button>
        ))}
      </div>

      <div className="card">
        {loading ? <div className="page-loading"><div className="spinner" /></div> : (
          <div className="table-wrap">
            <table>
              <thead>
                <tr>
                  <th>Employee</th>
                  <th>Version</th>
                  <th>Status</th>
                  <th>Generated</th>
                  <th>Approval Trail</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {letters.length === 0 ? (
                  <tr><td colSpan={6}><div className="empty-state">
                    <div className="empty-icon">◈</div>
                    <p>{tab === 'active' ? 'No active letters — click Generate Letter to start' : 'No completed letters yet'}</p>
                  </div></td></tr>
                ) : letters.map(l => {
                  const cfg        = STATUS_CFG[l.status] || {};
                  const isDeletable = canDelete && DELETABLE_STATUSES.has(l.status);

                  return (
                    <tr key={l._id}>
                      <td>
                        <div style={{ fontWeight: 500 }}>{l.employee_name}</div>
                        <div className="mono text-muted text-sm">{l.employee_code}</div>
                      </td>
                      <td><span className="badge badge-gray mono">v{l.version}</span></td>
                      <td><span className={`badge ${cfg.cls}`}>{cfg.label}</span></td>
                      <td className="mono text-muted text-sm">{new Date(l.created_at).toLocaleDateString('en-IN')}</td>
                      <td>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                          {(l.approval_history || []).map((h, i) => (
                            <div key={i} style={{ fontSize: 11, color: h.action === 'approve' || h.action === 'submitted' ? 'var(--green)' : h.action === 'reject' ? 'var(--red)' : 'var(--text-dim)' }}>
                              {h.user_name || h.role} → {h.action}
                            </div>
                          ))}
                          {!l.approval_history?.length && <span style={{ fontSize: 11, color: 'var(--text-dim)' }}>No actions yet</span>}
                        </div>
                      </td>
                      <td>
                        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                          {/* DOCX always downloadable */}
                          <button className="btn btn-sm btn-secondary" onClick={() => download(l._id, 'docx')}>↓ DOCX</button>
                          {/* PDF only post-approval */}
                          {['approved', 'issued'].includes(l.status) && (
                            <button className="btn btn-sm btn-secondary" onClick={() => download(l._id, 'pdf')}>↓ PDF</button>
                          )}
                          {/* Submit only for drafts */}
                          {l.status === 'draft' && (
                            <button className="btn btn-sm btn-primary" onClick={() => setSubmit(l)}>Submit →</button>
                          )}
                          {/* Delete: admin/hr_head only, draft/rejected only */}
                          {isDeletable && (
                            <button className="btn btn-sm btn-danger"
                              style={{ background: 'var(--red)', borderColor: 'var(--red)', color: 'white' }}
                              onClick={() => setDelete(l)}
                              title="Permanently delete this letter (Admin / HR Head only)">
                              ✕ Delete
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ── Modals ── */}
      {showGen && <GenerateModal employees={employees} templates={templates} onClose={() => setShowGen(false)} onDone={handleDone} />}

      {deleteTarget && (
        <DeleteLetterModal letter={deleteTarget} onClose={() => setDelete(null)} onDone={onDeleteDone} />
      )}

      {submitTarget && (
        <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setSubmit(null)}>
          <div className="modal" style={{ maxWidth: 400 }}>
            <h2 className="modal-title">Submit for Approval?</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 13, marginBottom: 16 }}>
              Offer letter for <strong style={{ color: 'var(--text)' }}>{submitTarget.employee_name}</strong> will enter the approval workflow and become locked for editing.
            </p>
            <div style={{ background: 'var(--surface-2)', borderRadius: 'var(--radius)', padding: 12, marginBottom: 20, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10 }}>
              {['HR Draft', '→', 'Manager', '→', 'HR Head', '→ ✓ Approved'].map((s, i) => (
                <span key={i} style={{ fontSize: 12, color: s.includes('✓') ? 'var(--green)' : s === '→' ? 'var(--border-bright)' : 'var(--text-muted)', fontFamily: 'var(--mono)' }}>{s}</span>
              ))}
            </div>
            <div className="modal-footer">
              <button className="btn btn-secondary" onClick={() => setSubmit(null)}>Cancel</button>
              <button className="btn btn-primary" onClick={submitLetter}>Submit</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
